Add this to a new file assets/script.js (or in a &lt;script&gt; tag in index.qmd):
``javascript fetch(https://docs.google.com/spreadsheets/d/10Lz86fUeqTrgBTdrjOa02zzM96G6_KhUVhZBbnuu940)   .then(response =&gt; response.json())   .then(data =&gt; {     // Parse data into themenu` object });
// Update categories based on occasion function updateCategories() { const occasion = document.getElementById(“occasion”).value; const categorySelect = document.getElementById(“category”); categorySelect.innerHTML = ‘– Select Category –’; categorySelect.disabled = !occasion;
if (occasion) { Object.keys(menu[occasion]).forEach(category =&gt; { const option = document.createElement(“option”); option.value = category; option.textContent = category; categorySelect.appendChild(option); }); } }
// Update items based on category function updateItems() { const occasion = document.getElementById(“occasion”).value; const category = document.getElementById(“category”).value; const itemSelect = document.getElementById(“item”); itemSelect.innerHTML = ‘– Select Item –’; itemSelect.disabled = !category;
if (category) { menu[occasion][category].forEach(item =&gt; { const option = document.createElement(“option”); option.value = item.name; option.textContent = ${item.name} ($${item.total.toFixed(2)}); itemSelect.appendChild(option); }); } }
// Update details (size, flavors, etc.) and calculate total function updateDetails() { const occasion = document.getElementById(“occasion”).value; const category = document.getElementById(“category”).value; const itemName = document.getElementById(“item”).value; const detailsContainer = document.getElementById(“details-container”); const orderSummary = document.getElementById(“order-summary”);
if (!itemName) { detailsContainer.innerHTML = ““; orderSummary.innerHTML = ’

Total: $0.00

’; return; }
// Find the selected item const item = menu[occasion][category].find(i =&gt; i.name === itemName); detailsContainer.innerHTML = `

&lt;p&gt;\${item.description || "Customize your order below:"}&lt;/p&gt;

&lt;!-- Size dropdown (example) --&gt;
&lt;label&gt;Size:
  &lt;select id="size"&gt;
    &lt;option value="Standard"&gt;Standard&lt;/option&gt;
    &lt;option value="Large"&gt;Large (+\$10)&lt;/option&gt;
  &lt;/select&gt;
&lt;/label&gt;

&lt;!-- Buttercream flavor (example) --&gt;
&lt;label&gt;Buttercream Flavor:
  &lt;select id="buttercream"&gt;
    &lt;option value="Vanilla"&gt;Vanilla&lt;/option&gt;
    &lt;option value="Chocolate"&gt;Chocolate&lt;/option&gt;
    &lt;option value="Strawberry"&gt;Strawberry&lt;/option&gt;
  &lt;/select&gt;
&lt;/label&gt;

&lt;!-- Message field --&gt;
&lt;label&gt;Custom Message:
  &lt;input type="text" id="message" placeholder="e.g., 'Happy Birthday!'"&gt;
&lt;/label&gt;
`;
// Calculate total price (base + adjustments) const basePrice = item.total; let totalPrice = basePrice;
// Example: Add $10 for “Large” size document.getElementById(“size”).addEventListener(“change”, (e) =&gt; { totalPrice = e.target.value === “Large” ? basePrice + 10 : basePrice; document.getElementById(“total-price”).textContent = totalPrice.toFixed(2); });
// Update total price display document.getElementById(“total-price”).textContent = totalPrice.toFixed(2); }

